/*
 * A LEARNER WRITES TO RICHARD (DBU-07). Identity is the session: no parameter names a person.
 * A message may be about one of her shared homework steps (it then shows in that homework's
 * thread as well as in Messages), and may carry up to 5 files she uploaded privately, checked
 * exactly as hand-ins are (DBU-06): hers, private, up to 50 MB, a kind on the list, and bytes
 * that are what the name says. Saved with mailPending; shared/Message mail tells the coach next.
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const me = String(Inputs.userId || '');
    if (!me) throw new Error('no session user');
    const q = (c, where) => Noodl.Records.query(c, where, { limit: 1000, plain: true });
    const MAX_BYTES = 50 * 1024 * 1024;
    const MAX_FILES = 5;
    const MEDIA = ['application/octet-stream'];
    const OFFICE = ['application/zip'];
    const TYPES = {
      pdf: ['application/pdf'], docx: OFFICE, pptx: OFFICE, xlsx: OFFICE,
      html: ['text/html'], htm: ['text/html'],
      png: ['image/png'], jpg: ['image/jpeg'], jpeg: ['image/jpeg'], webp: ['image/webp'],
      mp3: ['audio/mpeg'], m4a: MEDIA.concat(['audio/mp4']), mp4: MEDIA.concat(['video/mp4']), webm: MEDIA.concat(['video/webm', 'audio/webm'])
    };

    const body = String(Inputs.body || '').trim();
    const names = Array.isArray(Inputs.files) ? Inputs.files.map((x) => String(x || '')).filter(Boolean) : [];
    if (!body && !names.length) return refuse('Write your message first.');
    if (body.length > 5000) return refuse('Keep a message under 5,000 characters, or send it in two.');

    const stepId = String(Inputs.stepId || '');
    if (stepId) {
      const steps = await q('Step', { objectId: { equalTo: stepId } });
      const step = steps[0];
      if (!step || step.learner !== me || step.shared !== true || step.kind !== 'homework') return refuse('This homework is not one of yours. Reload the page.');
    }

    const attachments = [];
    if (names.length > MAX_FILES) return refuse('Attach up to ' + MAX_FILES + ' files to one message.');
    if (new Set(names).size !== names.length) return refuse('The same file is attached twice. Remove one and send again.');
    for (const name of names) {
      const rows = await q('_Files', { storedName: { equalTo: name } });
      const f = rows.length === 1 ? rows[0] : null;
      const owner = f && f.owner && typeof f.owner === 'object' ? f.owner.objectId : f && f.owner;
      // Never name a file that is not the caller's: its name is someone else's.
      if (!f || owner !== me) return refuse((names.length > 1 ? 'One of these files is' : 'That file is') + ' not one you uploaded. Attach it again.');
      const original = String(f.originalName || '');
      const said = (why) => refuse(names.length > 1 ? original + ': ' + why : why);
      if (f.private !== true) return said('That file was not uploaded privately. Attach it again.');
      if (Number(f.size) > MAX_BYTES) return said('That file is larger than 50 MB. Put it online and send the link instead.');
      const dot = original.lastIndexOf('.');
      const ext = dot > 0 ? original.slice(dot + 1).toLowerCase() : '';
      const allowed = TYPES[ext];
      if (!allowed) return said('Files of this kind can\'t be attached. Use Word, PowerPoint, Excel, PDF, HTML, an image (PNG, JPG, WebP), audio (MP3, M4A) or video (MP4, WebM), or send a link.');
      if (!allowed.includes(f.contentType)) return said('This file is not a real .' + ext + ' file. Save it again in that format, then attach it.');
      attachments.push({ file: name, name: original });
    }

    const created = await Noodl.Records.create('Message', {
      learner: me, author: me, step: stepId || null, body, attachments,
      readAt: null, mailPending: true, mailedAt: null
    }, { plain: true });
    await Noodl.Records.create('Doorbell', { learner: me, topic: 'message' },
      { acl: { [me]: { read: true }, 'role:staff': { read: true } } });

    Outputs.messageId = created.objectId || created.id;
    Outputs.mail = { learnerId: me, to: 'coach', at: Date.now() };
  } catch (e) {
    console.error('[dbu:sendMessage]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
